-- V32: 릴스 시드 (크리에이터 2 + 릴스 232)
-- 출처: 유튜브 레시피 릴스(@oh_mechu→오메추, @food_radio→푸드라디오) 다운로드 → S3 업로드.
-- video_url/thumbnail_url 은 상대 key (reels/{id}.mp4, thumbnails/{id}.webp).
--   응답 시 MediaUrlResolver 가 app.uploads.public-base-url(CloudFront)을 prepend 한다.
-- view_count 는 결정론적 placeholder(실측 아님). 좋아요/댓글은 시드하지 않음(실사용자 상호작용으로 채움).
-- recipe_id 는 레시피 DB 적재 후 별도 연결(현재 NULL). NOT EXISTS 가드로 idempotent.

-- 크리에이터
INSERT INTO creators (id, user_id, display_name, avatar_url, status) SELECT 1, NULL, '오메추', NULL, 'ACTIVE' WHERE NOT EXISTS (SELECT 1 FROM creators WHERE id = 1);
INSERT INTO creators (id, user_id, display_name, avatar_url, status) SELECT 2, NULL, '푸드라디오', NULL, 'ACTIVE' WHERE NOT EXISTS (SELECT 1 FROM creators WHERE id = 2);
ALTER TABLE creators ALTER COLUMN id RESTART WITH 3;

